def calc(expr: str) -> int:
    # Tokenize
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
            continue
        if c in '+-*/()':
            tokens.append((c, c))
            i += 1
            continue
        raise ValueError(f"Unexpected character: {c}")

    pos = [0]

    def peek():
        if pos[0] < len(tokens):
            return tokens[pos[0]]
        return (None, None)

    def advance():
        tok = tokens[pos[0]]
        pos[0] += 1
        return tok

    def parse_expr():
        val = parse_term()
        while True:
            t, _ = peek()
            if t == '+' or t == '-':
                advance()
                rhs = parse_term()
                if t == '+':
                    val = val + rhs
                else:
                    val = val - rhs
            else:
                break
        return val

    def parse_term():
        val = parse_factor()
        while True:
            t, _ = peek()
            if t == '*' or t == '/':
                advance()
                rhs = parse_factor()
                if t == '*':
                    val = val * rhs
                else:
                    # truncating division toward zero
                    q = abs(val) // abs(rhs)
                    if (val < 0) != (rhs < 0):
                        q = -q
                    val = q
            else:
                break
        return val

    def parse_factor():
        t, _ = peek()
        if t == '-':
            advance()
            return -parse_factor()
        return parse_primary()

    def parse_primary():
        t, v = peek()
        if t == 'NUM':
            advance()
            return v
        if t == '(':
            advance()
            val = parse_expr()
            t2, _ = peek()
            if t2 != ')':
                raise ValueError("Expected closing parenthesis")
            advance()
            return val
        raise ValueError(f"Unexpected token: {t}")

    result = parse_expr()
    if pos[0] != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result

